import SwiftUI
struct CardStackView: View { @EnvironmentObject private var appState: AppState; @Binding var actionRequest: SwipeAction?; @Binding var badgeAction: SwipeAction?; @State private var deck:[Job]=Job.mockJobs; var body: some View { ZStack { ForEach(Array(deck.prefix(4).enumerated()).reversed(), id:\.element.id){index,job in JobCardView(job:job).scaleEffect(1-CGFloat(index)*SwipeThresholds.stackScaleFactor).offset(y:-CGFloat(index)*SwipeThresholds.stackOffsetFactor).opacity(pow(0.9,Double(index))).zIndex(Double(4-index)).swipeCard(enabled:index==0){complete($0,job:job)} } }.animation(.cardPeel,value:deck).onAppear{deck=appState.jobs.isEmpty ? Job.mockJobs : appState.jobs}.onChange(of:actionRequest){_,request in if let request, let front=deck.first { complete(request,job:front); actionRequest=nil } } }
    private func complete(_ action: SwipeAction, job: Job){ appState.handle(action:action,for:job); badgeAction=action; withAnimation(.cardPeel){deck.removeAll{$0.id==job.id}; if let replacement=appState.jobs.filter({candidate in !deck.contains(candidate) && candidate.id != job.id}).randomElement(){deck.append(replacement)}} }
}
